// Croise les requêtes Google Search Console avec les 39 articles publiés,
// et désigne LA page à renforcer aujourd'hui.
//
// Changement de doctrine : on n'écrit plus d'article neuf. 337 articles
// publiés n'ont ramené que 23 visiteurs par mois — le volume n'était pas le
// problème, il l'a créé. Une page déjà en position 5-20 a des impressions :
// il lui manque quelques places, pas un cousin de plus.

const gsc = $('📊 Google Search Console — requêtes').first().json.rows || [];
const articles = $input.all().map((i) => i.json).flat();

const mots = (s) =>
  new Set(
    (s || '')
      .toLowerCase()
      .normalize('NFD').replace(/[\u0300-\u036f]/g, '')
      .split(/[^a-z0-9]+/)
      .filter((m) => m.length > 3)   // « des », « les », « chez » n'apprennent rien
  );

// Position 5 à 20 : au-delà, il faudrait tout refaire ; en deçà, le gain est mince.
const candidats = gsc
  .filter((r) => r.position >= 5 && r.position <= 20 && r.impressions >= 3)
  .map((r) => {
    const req = r.keys[0];
    const mr = mots(req);

    // On rattache la requête à l'article existant qui la couvre le mieux,
    // par recouvrement de vocabulaire. Pas de correspondance exacte possible :
    // une requête Google ne ressemble jamais tout à fait à un mot-clé cible.
    let meilleur = null, meilleurScore = 0;
    for (const a of articles) {
      const ma = mots(`${a.keyword} ${a.title}`);
      let commun = 0;
      for (const m of mr) if (ma.has(m)) commun++;
      const score = commun / Math.max(mr.size, 1);
      if (score > meilleurScore) { meilleurScore = score; meilleur = a; }
    }

    return {
      requete: req, position: r.position, impressions: r.impressions,
      clics: r.clicks, article: meilleur, affinite: meilleurScore,
      // Beaucoup d'impressions + position basse dans la fenêtre = marge maximale.
      score: r.impressions * (21 - r.position) * meilleurScore,
    };
  })
  // En dessous de la moitié des mots en commun, le rattachement est douteux :
  // mieux vaut ne rien faire que renforcer la mauvaise page.
  .filter((c) => c.article && c.affinite >= 0.5)
  .sort((a, b) => b.score - a.score);

if (!candidats.length) {
  return [{ json: { action: 'rien', raison: 'aucune requête en position 5-20 rattachable à un article' } }];
}

const c = candidats[0];
return [{
  json: {
    action: 'ameliorer',
    requete: c.requete,
    position: Math.round(c.position * 10) / 10,
    impressions: c.impressions,
    clics: c.clics,
    slug: c.article.slug,
    titre_actuel: c.article.title,
    contenu_actuel: c.article.content_html || '',
    // Les autres requêtes rattachées à la même page : autant de questions
    // auxquelles l'article devra répondre explicitement.
    requetes_liees: candidats
      .filter((x) => x.article.slug === c.article.slug && x.requete !== c.requete)
      .slice(0, 8).map((x) => x.requete),
  },
}];

// Construit la requête Claude en mode « améliorer ».
// L'article existe déjà : on le renforce sur les requêtes que Google montre
// comme réellement tapées, en gardant son slug — l'upsert le mettra à jour.

const c = $input.first().json;
if (c.action !== 'ameliorer') return [];

const prompt = `Tu es un expert SEO spécialisé en droit notarial français, rédacteur senior pour Notaires.io.

Notaires.io est une plateforme de prise de rendez-vous en ligne pour les études notariales, créée par une diplômée notaire. Les particuliers prennent rendez-vous en visio ou au cabinet, sur les disponibilités réelles de l'étude. Plus de 23 000 notaires référencés.

MISSION : améliorer un article EXISTANT, pas en écrire un nouveau.

Article actuel : "${c.titre_actuel}"
Il se positionne en ${c.position}ᵉ position sur « ${c.requete} », avec ${c.impressions} impressions et ${c.clics} clic(s) sur 30 jours.
Il est vu, mais pas cliqué, ou pas assez haut placé.

Autres requêtes qui mènent à cette page et auxquelles il doit répondre explicitement :
${(c.requetes_liees || []).map((r) => `- ${r}`).join('\n') || '- (aucune autre)'}

CONTENU ACTUEL :
${(c.contenu_actuel || '').slice(0, 12000)}

CONSIGNES :
- Reprends et enrichis ce contenu ; ne repars pas de zéro, ne perds rien de juste.
- Traite explicitement chaque requête listée, avec le vocabulaire employé par l'internaute.
- Ajoute ce qui manque : chiffres, délais, barèmes, cas particuliers, étapes concrètes.
- Nous sommes en 2026 : aucune référence à 2024 ou 2025 ne doit subsister.
- Les tarifs des actes sont fixés par décret. Notaires.io ne délivre aucun conseil juridique et n'est pas un office notarial.
- N'annonce jamais de "1er rendez-vous offert" : cette accroche n'est pas la nôtre.
- 1 800 à 2 500 mots, plus dense que l'original.

Réponds UNIQUEMENT avec un objet JSON valide (sans markdown ni texte autour) :
{
  "meta_title": "titre <title>, 55-60 caractères, mot-clé en début",
  "meta_description": "meta description 140-155 caractères avec appel à l'action",
  "h1": "titre H1 engageant",
  "excerpt": "résumé 120-150 mots, mot-clé dans les 50 premiers",
  "intro": "introduction 80-100 mots",
  "content_html": "article HTML complet : h2, h3, p, ul/li, strong",
  "faq": [{ "q": "question telle qu'elle est tapée", "r": "réponse 60-80 mots" }],
  "category": "Succession|Immobilier|Mariage|Famille|Donation|Guide|FAQ|Local",
  "reading_time": 9
}

5 à 7 sections H2, 5 à 8 questions de FAQ reprenant les requêtes ci-dessus.`;

return [{
  json: {
    // Opus 5 : même prix d'entrée que Sonnet 4.6, nettement meilleur en rédaction.
    // 16 000 tokens de sortie : 4 096 tronquait les articles en plein milieu.
    body: JSON.stringify({
      model: 'claude-opus-5',
      max_tokens: 16000,
      messages: [{ role: 'user', content: prompt }],
    }),
    slug: c.slug,          // on garde le slug : c'est ce qui fait l'UPDATE
    cible: c,
  },
}];

// Parse la réponse de Claude et réutilise le slug de l'article existant.
// C'est ce slug, inchangé, qui fait que l'upsert Supabase MET À JOUR la page
// au lieu d'en créer une nouvelle. Ne jamais y ajouter d'horodatage : c'est
// exactement ce qui avait produit 337 articles pour 39 sujets.

const response = $input.item.json;
const amont = $('🧠 Construire prompt Claude').item.json;

let rawText;
try {
  rawText = response.content[0].text;
} catch (e) {
  throw new Error('Réponse Claude illisible: ' + JSON.stringify(response).substring(0, 200));
}

let art;
try {
  art = JSON.parse(rawText.replace(/^```json\s*/i, '').replace(/\s*```$/i, '').trim());
} catch (e) {
  throw new Error('JSON invalide dans réponse Claude: ' + rawText.substring(0, 400));
}

const article = {
  slug: amont.slug,                       // ← slug conservé, donc UPDATE
  title: art.h1 || art.meta_title || amont.cible.titre_actuel,
  meta_title: art.meta_title || null,
  meta_description: art.meta_description || null,
  excerpt: art.excerpt || null,
  h1: art.h1 || null,
  intro: art.intro || null,
  content_html: art.content_html || '',
  faq_json: art.faq || null,
  category: art.category || 'Guide',
  keyword: amont.cible.requete,
  keyword_type: 'gsc-amelioration',
  reading_time: art.reading_time || 9,
  published: true,
};

return [{ json: { article, cible: amont.cible } }];

const article = $('🔍 Parser réponse Claude').item.json.article;
const kw = $('🔍 Parser réponse Claude').item.json.keyword;
const date = new Date().toLocaleDateString('fr-FR', { weekday:'long', day:'numeric', month:'long', year:'numeric' });
const url = `https://notaires.io/blog/${article.slug}`;

const gscBadge = kw.source === 'gsc'
  ? `<div style="background:#dcfce7;border:1px solid #86efac;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:13px">📊 <strong>GSC</strong> — Position actuelle : <strong>${kw.gsc_position}</strong> · ${kw.gsc_impressions} impressions · ${kw.gsc_ctr}% CTR</div>`
  : `<div style="background:#fef9c3;border:1px solid #fde047;border-radius:8px;padding:10px 14px;margin-bottom:12px;font-size:13px">📋 Source : liste prédéfinie (données GSC pas encore suffisantes)</div>`;

const html = `<!DOCTYPE html><html><head><meta charset="utf-8"></head><body style="font-family:-apple-system,sans-serif;max-width:640px;margin:0 auto;padding:20px;background:#fff;color:#1f2937"><div style="background:linear-gradient(135deg,#1c4587,#2d5dbf);color:white;padding:20px 24px;border-radius:12px;margin-bottom:18px"><div style="font-size:12px;opacity:.75;margin-bottom:4px">✅ SEO Agent Notaires.io · ${date}</div><div style="font-size:20px;font-weight:700">Article publié automatiquement</div><div style="font-size:13px;opacity:.9;margin-top:4px">🎯 <strong>${kw.keyword}</strong> · ${article.category}</div></div>${gscBadge}<div style="background:#f0f7ff;border:1px solid #bfdbfe;border-radius:10px;padding:14px 18px;margin-bottom:14px"><div style="font-size:11px;font-weight:700;text-transform:uppercase;color:#2d5dbf;margin-bottom:8px">📌 BALISES SEO</div><div style="margin-bottom:6px"><span style="font-size:11px;color:#6b7280">TITLE (${(article.meta_title||'').length} car)</span><br><strong style="color:#1c4587">${article.meta_title}</strong></div><div style="margin-bottom:6px"><span style="font-size:11px;color:#6b7280">META DESC</span><br>${article.meta_description}</div><div><span style="font-size:11px;color:#6b7280">URL</span><br><a href="${url}" style="color:#2d5dbf;font-family:monospace">${url}</a></div></div><div style="background:#ecfdf5;border:1px solid #6ee7b7;border-radius:10px;padding:14px 18px;margin-bottom:14px;text-align:center"><div style="font-size:15px;font-weight:700;color:#065f46;margin-bottom:8px">🚀 Article en ligne maintenant</div><a href="${url}" style="display:inline-block;background:#059669;color:white;padding:10px 20px;border-radius:8px;text-decoration:none;font-weight:600;font-size:14px">Voir l'article →</a></div><div style="background:#f9fafb;border:1px solid #e5e7eb;border-radius:10px;padding:14px 18px;margin-bottom:14px"><h3 style="color:#1c4587;margin:0 0 6px;font-size:17px">${article.h1}</h3><p style="color:#374151;font-size:14px;line-height:1.6;margin:0">${article.excerpt||article.intro||''}</p></div><div style="text-align:center;color:#9ca3af;font-size:11px;border-top:1px solid #f3f4f6;padding-top:12px">Agent SEO autonome · <a href="https://notaires.io/blog" style="color:#2d5dbf">notaires.io/blog</a></div></body></html>`;

return [{ json: { subject: `✅ Article publié : "${kw.keyword}" — notaires.io/blog/${article.slug}`, html } }];

// Volet GEO : signaler la page mise à jour à IndexNow.
//
// Bing prend les URL en quelques minutes là où Google met des semaines — et
// ChatGPT s'appuie sur l'index de Bing pour ses recherches web. C'est le
// canal où notaires.io peut devancer des concurrents mieux installés sur
// Google : les moteurs de réponse citent qui répond clairement, pas qui a
// le plus d'ancienneté.
const slug = $('🔍 Parser réponse Claude').first().json.article.slug;
return [{
  json: {
    host: 'notaires.io',
    key: "b36c029fbecfe439b305e7b1a6dc7aab",
    keyLocation: "https://notaires.io/b36c029fbecfe439b305e7b1a6dc7aab.txt",
    urlList: [`https://notaires.io/blog/${slug}`],
  },
}];
